from fastapi import FastAPI
from fastapi.responses import HTMLResponse
from pydantic import BaseModel

app = FastAPI(title="PromptCraft.ai")

class PromptRequest(BaseModel):
    prompt: str

PAGE = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>PromptCraft.ai</title>\n<script src="https://cdn.tailwindcss.com"></script>\n</head>\n<body class="bg-slate-950 text-white">\n<!-- Netlify Deploy Ready -->\n<div id="app"></div>\n<script>\nconst app=document.getElementById(\'app\');\nfunction home(){\napp.innerHTML=`<header class="fixed top-0 w-full z-50 bg-slate-950/80 backdrop-blur border-b border-white/10"><div class="max-w-7xl mx-auto h-16 px-5 flex justify-between items-center"><b class="text-xl"><span class="text-blue-400">Prompt</span>Craft<span class="text-purple-400">.ai</span></b><div class="flex gap-2"><button onclick="tools()" class="px-3 py-2 text-sm">AI Tools</button><button onclick="blog()" class="px-3 py-2 text-sm">Blog</button><button onclick="chat()" class="px-4 py-2 rounded-lg bg-gradient-to-r from-blue-600 to-purple-600 font-bold">Try AI</button></div></div></header>\n<main class="pt-16"><section class="min-h-[680px] flex items-center text-center px-5 bg-[radial-gradient(circle_at_50%_0%,rgba(59,130,246,.25),transparent_40%)]"><div class="max-w-5xl mx-auto"><span class="px-4 py-2 rounded-full bg-blue-500/10 border border-blue-400/20 text-blue-300">✦ AI for modern business</span><h1 class="text-5xl sm:text-7xl font-black mt-8">Work smarter.<br><span class="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 via-indigo-400 to-purple-500">Create with AI.</span></h1><p class="max-w-2xl mx-auto text-slate-400 text-lg mt-7">AI chat, prompts, coding, content and business tools in one platform.</p><button onclick="chat()" class="mt-9 px-7 py-4 rounded-xl bg-gradient-to-r from-blue-600 to-purple-600 font-bold">Start Creating →</button></div></section>\n<section class="max-w-7xl mx-auto px-5 py-20"><h2 class="text-4xl font-black">AI tools for your work</h2><div class="grid md:grid-cols-3 gap-4 mt-8">${card(\'🤖\',\'AI Chat\',\'Your intelligent assistant.\')}${card(\'⚡\',\'Prompt Generator\',\'Create powerful prompts.\')}${card(\'💻\',\'Coding AI\',\'Build and improve code.\')}</div></section></main></div>`;\n}\nfunction card(i,t,d){return `<div class="p-6 rounded-2xl bg-white/5 border border-white/10"><div class="text-3xl">${i}</div><h3 class="font-bold text-lg mt-5">${t}</h3><p class="text-slate-400 mt-2">${d}</p><button onclick="chat()" class="text-indigo-400 mt-5">Open →</button></div>`}\nfunction tools(){app.innerHTML=`<main class="max-w-7xl mx-auto px-5 pt-28"><button onclick="home()">← Home</button><h1 class="text-4xl font-black mt-5">AI Tools</h1><div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-4 mt-8">${[\'AI Chat\',\'Prompt Generator\',\'Coding Assistant\',\'Content AI\',\'Business Planner\',\'Study Coach\',\'Marketing AI\',\'Creative AI\'].map(x=>card(\'✦\',x,\'Ready for your AI workflow.\')).join(\'\')}</div></main>`}\nfunction blog(){app.innerHTML=`<main class="max-w-7xl mx-auto px-5 pt-28"><button onclick="home()">← Home</button><h1 class="text-4xl font-black mt-5">Blog</h1><button onclick="alert(\'Blog editor will use the Python database in the next stage.\')" class="mt-6 px-4 py-2 rounded-lg bg-gradient-to-r from-blue-600 to-purple-600">+ New Article</button><div class="grid md:grid-cols-3 gap-4 mt-8">${[\'How AI grows a business\',\'10 better coding prompts\',\'Build an AI workflow\'].map(x=>`<article class="p-6 rounded-2xl bg-white/5 border border-white/10"><h2 class="font-bold text-lg">${x}</h2><p class="text-slate-400 mt-2">Practical AI ideas.</p></article>`).join(\'\')}</div></main>`}\nfunction chat(){app.innerHTML=`<main class="max-w-5xl mx-auto px-5 pt-10"><button onclick="home()">← Home</button><h1 class="text-3xl font-black mt-6">AI Chat</h1><div class="mt-6 rounded-2xl border border-white/10 overflow-hidden"><div id="messages" class="h-[55vh] overflow-y-auto p-5"><div class="p-4 rounded-xl bg-indigo-500/10 max-w-xl">Hello! Tell me what you want to create.</div></div><div class="p-4 border-t border-white/10"><textarea id="q" class="w-full bg-slate-900 p-4 rounded-xl" rows="3" placeholder="Describe your idea..."></textarea><button onclick="send()" class="float-right mt-3 px-5 py-3 rounded-xl bg-gradient-to-r from-blue-600 to-purple-600 font-bold">Generate</button><div class="clear-both"></div></div></div></main>`}\nasync function send(){const q=document.getElementById(\'q\'),v=q.value.trim();if(!v)return;const m=document.getElementById(\'messages\');m.innerHTML+=`<div class="ml-auto max-w-xl p-4 bg-white/5 rounded-xl mt-3">${safe(v)}</div>`;q.value=\'\';try{const r=await fetch(\'/api/prompt\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({prompt:v})});const d=await r.json();m.innerHTML+=`<div class="max-w-xl p-4 bg-indigo-500/10 rounded-xl mt-3 whitespace-pre-line">${safe(d.prompt)}</div>`}catch(e){m.innerHTML+=`<div class="text-red-300 mt-3">Backend not connected.</div>`}}\nfunction safe(s){return s.replace(/[&<>]/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\'}[c]))}\nhome();\n</script></body></html>'

@app.get("/", response_class=HTMLResponse)
def home():
    return PAGE

@app.get("/api/health")
def health():
    return {"ok": True, "service": "PromptCraft.ai"}

@app.post("/api/prompt")
def generate_prompt(data: PromptRequest):
    return {"ok": True, "prompt": f"Act as an expert AI assistant.\n\nGoal: {data.prompt}\n\nGive a clear, practical, structured answer with examples.\n\nThis endpoint is ready to connect to a real AI provider."}
